Short plan (read-only as requested):

### 1) Update src/api/account.ts

Add imports (createUser, UserError, createSession) and a new POST /api/signup route in accountRoutes.

Exact code to write:

```ts
import { getUser, publicUser, createUser, UserError } from "../auth/users.ts";
import { revokeSession, createSession } from "../auth/session.ts";
import { field, html, json, sessionOf, type Route } from "./router.ts";
import { accountPage } from "../ui/pages.ts";

export const accountRoutes: Route[] = [
  {
    method: "GET",
    path: "/api/me",
    handler: (req) => {
      const session = sessionOf(req);
      const user = session && getUser(session.userId);
      return user ? json(200, publicUser(user)) : json(401, { error: "not signed in" });
    },
  },
  {
    method: "GET",
    path: "/account",
    handler: (req) => {
      const session = sessionOf(req);
      const user = session && getUser(session.userId);
      return user ? html(200, accountPage(publicUser(user))) : html(401, "<p>Please sign in.</p>");
    },
  },
  {
    method: "POST",
    path: "/api/signup",
    handler: (req) => {
      const email = field(req.body, "email");
      const name = field(req.body, "name");
      const password = field(req.body, "password");
      if (!email || !name || !password) return json(400, { error: "email, name, and password are required" });
      try {
        const user = createUser(email, name, password);
        const session = createSession(user.id);
        return json(201, { token: session.token, user: publicUser(user) });
      } catch (err) {
        if (err instanceof UserError) return json(400, { error: err.message });
        throw err;
      }
    },
  },
  {
    method: "POST",
    path: "/api/logout",
    handler: (req) => {
      const session = sessionOf(req);
      if (!session) return json(401, { error: "not signed in" });
      revokeSession(session.token);
      return json(200, { ok: field(req.body, "reason") ?? true });
    },
  },
];
```

Notes: signup registers via createUser(email, name, password) and signs in immediately by createSession(user.id) (same as login). Returns 201 with {token, user: publicUser(user)}. UserError -> 400 {error}. Route added to accountRoutes (position between /account and /api/logout is fine; accountRoutes are spread into routes, so order within array doesn’t affect behavior).

### 2) Add test/signup.test.ts

Create a new test file with node:test + assert, using the same call/app/reset pattern as test/api.test.ts.

Exact code to write:

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates a user and signs in returning 201 with token and public user", async () => {
  const res = await call("POST", "/api/signup", {
    email: "bob@example.com",
    name: "Bob",
    password: "supersecret",
  });
  assert.equal(res.status, 201);
  const body = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.ok(typeof body.token === "string" && body.token.length > 0);
  assert.deepEqual(body.user, { id: body.user.id, email: "bob@example.com", name: "Bob" });
});

test("signup rejects duplicate email with 400", async () => {
  await call("POST", "/api/signup", { email: "bob@example.com", name: "Bob", password: "supersecret" });
  const res = await call("POST", "/api/signup", { email: "BOB@example.com", name: "Robert", password: "anotherpass" });
  assert.equal(res.status, 400);
  assert.equal((res.body as { error: string }).error, "email already registered");
});

test("signup rejects invalid email and short password with 400", async () => {
  const badEmail = await call("POST", "/api/signup", { email: "not-an-email", name: "X", password: "supersecret" });
  assert.equal(badEmail.status, 400);
  const shortPass = await call("POST", "/api/signup", { email: "alice@example.com", name: "Alice", password: "short" });
  assert.equal(shortPass.status, 400);
});
```

Notes: mirrors existing test style; tests cover success (201, token + publicUser), duplicate email (400), and validation errors (400).
